// app.js — ported from academia.html. See
// /root/.claude/plans/your-job-is-to-iterative-trinket.md §H1 for the exact
// line-by-line map this file follows, and
// /root/gg-arena-vibe-2/entrainement-handoff/S4-notes.md for the
// classification (byte-for-byte / one enumerated change / rewrite) of every
// function below.
//
// No wrapping IIFE, on purpose: academia.html's original <script> block was
// plain top-level `function` declarations, which is exactly what makes them
// reachable as globals for the inline onclick="..."/oninput="..." handlers
// generated by renderDay(). Node's CommonJS loader gives this same file its
// own module scope automatically when required by tests, so no IIFE is
// needed for that side either.

// --- API bridge: window globals in the browser, require() under node --test.
// New code (not from academia.html) — the old app had no client-side auth or
// Sheets client, the server held both. Guarded so require('./app.js') under
// node never throws, per H3.
var SheetsAPI = (typeof window !== 'undefined' && window.Sheets) ? window.Sheets :
    (typeof require === 'function' ? (function () { try { return require('./sheets.js'); } catch (e) { return null; } })() : null);
var AuthAPI = (typeof window !== 'undefined' && window.Auth) ? window.Auth :
    (typeof require === 'function' ? (function () { try { return require('./auth.js'); } catch (e) { return null; } })() : null);

var sheetsClient = null;
if (SheetsAPI && typeof SheetsAPI.createClient === 'function') {
    try {
        sheetsClient = SheetsAPI.createClient({
            // Per S3-notes.md: sheets.js's default onAuthFailure bridge
            // calls Auth.handleAuthFailure() with no appState, which loses
            // the active tab + scroll restore on a mid-session 401/403.
            // Pass a closure carrying the current appState instead.
            onAuthFailure: function () {
                return AuthAPI ? AuthAPI.handleAuthFailure(undefined, currentAppState()) : undefined;
            }
        });
    } catch (e) {
        // No storage/fetch available (e.g. under node --test with no
        // window/localStorage) — sheetsClient stays null, only the pure
        // functions (parseDays/injectPastComments/renderDay) are testable
        // there, which is exactly H3's requirement.
        sheetsClient = null;
    }
}

// Restore the pre-redirect active tab + scroll after the OAuth round trip
// (auth.js stashes/returns this as `appState`; academia.html never had this
// concept since the old server held the session). New code.
function currentAppState() {
    var tab = 'treino';
    if (typeof document !== 'undefined') {
        var activeTabBtn = document.querySelector('.tab.active');
        if (activeTabBtn) {
            var onclickAttr = activeTabBtn.getAttribute('onclick') || '';
            var m = onclickAttr.match(/switchTab\('([^']+)'/);
            if (m) tab = m[1];
        }
    }
    var scroll = (typeof window !== 'undefined' && typeof window.scrollY === 'number') ? window.scrollY : 0;
    return { tab: tab, scroll: scroll };
}

function restoreAppState(appState) {
    if (!appState || typeof document === 'undefined') return;
    if (appState.tab && appState.tab !== 'treino') {
        var btn = document.querySelector('.tab[onclick*="switchTab(\'' + appState.tab + '\'"]');
        if (btn) switchTab(appState.tab, btn);
    }
    if (typeof appState.scroll === 'number' && typeof window !== 'undefined' && window.scrollTo) {
        window.scrollTo(0, appState.scroll);
    }
}

// --- Token freshness on writes + pending-write replay ------------------
// New code (not from academia.html — the old app's server held the
// credential, so a browser-side token could never go stale mid-session).
//
// The OAuth implicit flow has no refresh token, and Google's authorization
// endpoint refuses to render in an iframe, so the ONLY way to renew the
// 1 h access token is a top-level prompt=none redirect. That is why an edit
// made after the token expired used to surface as an "auth failure" alert
// and lose the typed value: sheets.js fired the redirect from inside the
// PUT, and the in-flight edit died with the page.
//
// So every write now checks the token BEFORE it goes out. If the token is
// gone or expired, the edit is parked in sessionStorage (which survives the
// round trip to Google), the silent renewal is started, and the queue is
// replayed on the way back in — the user sees a brief reflow instead of an
// error, and the value lands.

var PENDING_WRITES_KEY = 'entr.pendingWrites';

// RPE always lives in column O (index 14) — same constant sheets.js pins
// updateRPE to. Only used here to give a parked RPE write a target key that
// can be de-duplicated against the other writes on that row.
var RPE_COL_INDEX = (SheetsAPI && typeof SheetsAPI.RPE_COLUMN_INDEX === 'number') ? SheetsAPI.RPE_COLUMN_INDEX : 14;

function pendingWritesStorage() {
    try {
        return (typeof window !== 'undefined' && window.sessionStorage) ? window.sessionStorage : null;
    } catch (e) {
        return null; // Safari private mode / storage disabled
    }
}

function readPendingWrites() {
    var storage = pendingWritesStorage();
    if (!storage) return [];
    var raw = storage.getItem(PENDING_WRITES_KEY);
    if (!raw) return [];
    try {
        var parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
        return [];
    }
}

function writePendingWrites(list) {
    var storage = pendingWritesStorage();
    if (!storage) return;
    if (!list || list.length === 0) storage.removeItem(PENDING_WRITES_KEY);
    else storage.setItem(PENDING_WRITES_KEY, JSON.stringify(list));
}

function samePendingTarget(a, b) {
    return a.kind === b.kind && a.sheetName === b.sheetName &&
        a.rowIndex === b.rowIndex && a.colIndex === b.colIndex;
}

// Queues one write, de-duplicated on (kind, sheet, row, col) so a field
// edited twice before the redirect replays only its latest value.
function queuePendingWrite(entry) {
    if (!entry) return;
    var list = readPendingWrites().filter(function (w) {
        return !samePendingTarget(w, entry);
    });
    list.push(entry);
    writePendingWrites(list);
}

// Renders the "Connexion à Google requise. [Se reconnecter]" prompt into
// the given error element. Shared by the load path and the write path so
// both dead ends look the same.
function renderReconnectPrompt(errorEl) {
    if (typeof document === 'undefined' || !AuthAPI) return;
    var error = errorEl || document.getElementById('error');
    if (!error) return;
    error.textContent = '';
    var msg = document.createElement('span');
    msg.textContent = AuthAPI.MESSAGES.SIGN_IN_REQUIRED + '. ';
    var btn = document.createElement('button');
    btn.textContent = AuthAPI.MESSAGES.RECONNECT;
    btn.onclick = function () { AuthAPI.reconnect(undefined, currentAppState()); };
    error.appendChild(msg);
    error.appendChild(btn);
    error.style.display = 'block';
}

// The pre-flight every write goes through. Returns true when a valid token
// is in hand and the caller may proceed. Returns false after parking
// `pending` and starting a renewal (or, when only an interactive sign-in
// can help, after showing the reconnect prompt with the edit still parked
// so it replays once the user signs back in).
function ensureTokenBeforeWrite(pending) {
    if (!AuthAPI) return true; // no auth layer (node --test) — nothing to check
    if (AuthAPI.getValidToken()) return true;

    queuePendingWrite(pending);

    if (!AuthAPI.needsReconnect()) {
        var result = AuthAPI.handleAuthFailure(undefined, currentAppState());
        if (result && result.status === 'redirecting') return false; // navigating now
    }

    renderReconnectPrompt();
    return false;
}

// Backstop for the race the pre-flight cannot cover: the token was still
// valid when the PUT left, and Google rejected it anyway (401/403, or a
// revoked session). sheets.js already invoked the auth failure handler, so
// all that's left is to park the edit for replay and — when no redirect is
// under way — show the reconnect prompt. Returns true when it owned the
// error, i.e. the caller must NOT alert.
function handleWriteAuthFailure(err, pending) {
    if (!err || !err.authRequired) return false;
    queuePendingWrite(pending);
    if (!(err.authResult && err.authResult.status === 'redirecting')) {
        renderReconnectPrompt();
    }
    return true;
}

// Replays whatever the last expiry parked, oldest first. Called on load
// once a valid token is in hand and BEFORE the network read, so the
// re-render shows the replayed values. Anything that fails again stays
// queued for the next attempt.
async function flushPendingWrites() {
    var list = readPendingWrites();
    if (!list.length || !sheetsClient) return 0;

    writePendingWrites([]); // take them off first, re-park only real failures

    var failed = [];
    for (const write of list) {
        try {
            if (write.kind === 'rpe') {
                await sheetsClient.updateRPE(write.sheetName, write.rowIndex, write.value);
            } else {
                await sheetsClient.updateCell(write.sheetName, write.rowIndex, write.colIndex, write.value);
            }
        } catch (e) {
            console.error('Pending write replay failed', write, e);
            failed.push(write);
        }
    }
    if (failed.length) writePendingWrites(failed);
    return list.length - failed.length;
}

// injectPastComments — JS port of server.py's inject_past_exercise_comments
// (server.py:1571-1691, read with sed per H2, never imported). Same
// indexing ({dayNum: {lower(name): [entries]}}), same match priority (exact
// sets+reps, heaviest on ties; else heaviest same-name entry in that JOUR),
// same "Passé: {sets}x{reps} @{load}kg RPE {rpe}" prefix prepended into
// column R (index 17, row padded to 18 cells), same "already has a Passé:"
// skip, same RPE-perçu-falls-back-to-donné rule, same "\n\n" separator.
// server.py only ever calls this with (current_tab, past_tab) — never the
// reverse — for the /ws2/entrainement/data response; this file calls it the
// same way, on the same two tabs.
//
// ONE deliberate divergence from server.py (bug fix, see fuseSets below):
// both passes now carry a merged "Séries" cell (column K) down its exercise
// group, exactly as parseDays does. server.py required a literal non-empty
// K on both sides, which silently dropped the "Passé: ..." line for every
// exercise but the first of a merged group.
function injectPastComments(currentData, pastData) {
    if (!currentData || !currentData.values || !pastData || !pastData.values) {
        return currentData;
    }

    var currentValues = currentData.values;
    var pastValues = pastData.values;

    // Mirrors Python's `str(row[idx]).strip()` for a row that may be
    // shorter than idx (ragged rows from the Sheets API): Python's
    // `len(row) > idx` guard, else "".
    function cellStr(row, idx) {
        if (row.length > idx) {
            var v = row[idx];
            return (v === null || v === undefined) ? '' : String(v).trim();
        }
        return '';
    }

    // Mirrors parse_load_value: strip everything but digits/./, , replace
    // ',' with '.', float() it — but Python's float() raises (caught ->
    // -1.0) on things like "1.2.3" (two dots) where JS's lenient
    // parseFloat("1.2.3") would silently return 1.2. This regex enforces
    // "at most one dot" so the two languages agree on every input.
    function parseLoadValue(loadStr) {
        if (!loadStr) return -1.0;
        var s = String(loadStr);
        var clean = '';
        for (var i = 0; i < s.length; i++) {
            var c = s.charAt(i);
            if ((c >= '0' && c <= '9') || c === '.' || c === ',') clean += c;
        }
        var normalized = clean.replace(/,/g, '.');
        if (normalized === '' || normalized === '.' || !/^\d*\.?\d*$/.test(normalized)) return -1.0;
        var f = parseFloat(normalized);
        return isNaN(f) ? -1.0 : f;
    }

    // Python's max(list, key=...) keeps the FIRST element on a tie (it only
    // replaces on strictly-greater). Mirrored here with a plain scan rather
    // than Array.reduce to keep that first-wins-ties behaviour obvious.
    function heaviest(list) {
        var best = list[0];
        for (var i = 1; i < list.length; i++) {
            if (list[i].load_val > best.load_val) best = list[i];
        }
        return best;
    }

    // The one row-is-an-exercise test, shared by both passes below. Same
    // rule server.py used inline: a non-empty column G that is neither the
    // "EXERCICE" header nor a "JOUR ..." banner.
    function isExerciseName(name) {
        return !!name && name.toUpperCase() !== 'EXERCICE' && name.toUpperCase().indexOf('JOUR') === -1;
    }

    // Merged "Séries" cells: the sheet fuses column K down an exercise
    // group, so only the FIRST row of the group carries a value. parseDays
    // already compensates ("Handle Merged Sets Cells (Fusion logic)"), but
    // server.py's injector did not — it required a non-empty column K on
    // both sides, so every exercise after the first in a merged group was
    // neither indexed from the past week nor injected into the current one,
    // and its "Passé: ..." line silently never appeared. This mirrors
    // parseDays' rules exactly: carry the last value over a blank K on a
    // real exercise row, reset on a row with no name (and, at the call
    // sites, on every new JOUR).
    function fuseSets(name, sets, state) {
        if (isExerciseName(name)) {
            if (sets) state.lastSets = sets;
            else if (state.lastSets) return state.lastSets;
        } else if (!name) {
            state.lastSets = null;
        }
        return sets;
    }

    // 1. Map past exercises by Day Number -> Name -> List of entries
    var pastMap = {};
    var currentPastDay = null;

    var pastSets = { lastSets: null };

    pastValues.forEach(function (row) {
        if (row.length > 2) {
            var val = cellStr(row, 2).toUpperCase();
            if (val.indexOf('JOUR') !== -1) {
                var match = /JOUR\s*(\d+)/.exec(val);
                if (match) {
                    currentPastDay = parseInt(match[1], 10);
                    if (!(currentPastDay in pastMap)) pastMap[currentPastDay] = {};
                    pastSets.lastSets = null; // new day — never carry across
                }
            }
        }

        if (currentPastDay === null) return;

        var name = cellStr(row, 6);
        var sets = fuseSets(name, cellStr(row, 10), pastSets);

        if (isExerciseName(name) && sets) {
            var normName = name.toLowerCase();
            var reps = cellStr(row, 11);
            var load = cellStr(row, 13);

            // RPE: prefer perçu (O=14), fall back to donné (M=12)
            var rpe = cellStr(row, 14);
            if (!rpe) rpe = cellStr(row, 12);

            var entry = {
                sets: sets,
                reps: reps,
                load: load,
                rpe: rpe,
                load_val: parseLoadValue(load)
            };

            if (!(normName in pastMap[currentPastDay])) pastMap[currentPastDay][normName] = [];
            pastMap[currentPastDay][normName].push(entry);
        }
    });

    // 2. Iterate current values and inject
    var currentDayNum = null;
    var currentSets = { lastSets: null };

    currentValues.forEach(function (row) {
        if (row.length > 2) {
            var val = cellStr(row, 2).toUpperCase();
            if (val.indexOf('JOUR') !== -1) {
                var match = /JOUR\s*(\d+)/.exec(val);
                if (match) {
                    currentDayNum = parseInt(match[1], 10);
                    currentSets.lastSets = null; // new day — never carry across
                }
            }
        }

        if (currentDayNum === null) return;

        var name = cellStr(row, 6);
        var sets = fuseSets(name, cellStr(row, 10), currentSets);

        if (isExerciseName(name) && sets) {
            var reps = cellStr(row, 11);
            var normName = name.toLowerCase();

            var dayExercises = pastMap[currentDayNum] || {};
            var candidates = dayExercises[normName] || [];

            var selectedPast = null;

            if (candidates.length > 0) {
                // Priority 1: Exact Sets AND Reps match
                var exactMatches = candidates.filter(function (c) {
                    return c.sets === sets && c.reps === reps;
                });

                if (exactMatches.length > 0) {
                    selectedPast = heaviest(exactMatches);
                } else {
                    // Priority 2: same name, same day, heaviest
                    selectedPast = heaviest(candidates);
                }
            }

            if (selectedPast) {
                var pastStr = 'Passé: ' + selectedPast.sets + 'x' + selectedPast.reps +
                    ' @' + selectedPast.load + 'kg RPE ' + selectedPast.rpe;

                // Ensure column R (17) exists
                while (row.length < 18) row.push('');

                var currentComment = cellStr(row, 17);

                // Prepend if not already present
                if (currentComment.indexOf('Passé:') === -1) {
                    if (currentComment) {
                        row[17] = pastStr + '\n\n' + currentComment;
                    } else {
                        row[17] = pastStr;
                    }
                }
            }
        }
    });

    return currentData;
}

// switchTab — academia.html:531-547, one enumerated change: the
// `historico` (Perfs) branch is dropped, nothing else touched.
function switchTab(viewId, element) {
    // Update Tab styles
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    element.classList.add('active');
    
    // Update View visibility
    document.querySelectorAll('.view-section').forEach(v => v.classList.remove('active'));
    document.getElementById(viewId + '-view').classList.add('active');

    if (viewId === 'passados') {
        loadPastData();
    } else if (viewId === 'futuros') {
        loadFutureData();
    }
}

// pastDataLoaded — academia.html:549 (`let pastDataLoaded = false;`). Not
// covered by any H1 table range (it sits between switchTab and
// loadFutureData, alongside the now-deleted chartsLoaded/allChartData
// charts state), but it's read/written by loadPastData below and would
// throw a ReferenceError if dropped. Kept; chartsLoaded/allChartData were
// charts-only and are not.
let pastDataLoaded = false;

// nextWeekCache — memoises the next-week sheet loadFutureData fetches, so
// switching to "À venir" repeatedly costs one network call, not one per
// switch. Reset next to pastDataLoaded whenever a completed day changes what
// the other tabs must show. Shape: {title, data}.
let nextWeekCache = null;

// Heading that separates the next-week block from the rest of this week's
// remaining days, so the two never read as one continuous list.
function appendWeekHeading(container, label) {
    const heading = document.createElement('h2');
    heading.style.cssText = 'margin: 24px 0 4px 0; color: #888; text-transform: uppercase; font-size: 0.8em; letter-spacing: 1px;';
    heading.textContent = label;
    container.appendChild(heading);
}

// loadFutureData — academia.html:553-581, one change: the tab no longer stops
// at the end of the current sheet.
//
// It only ever listed the days left in the CURRENT week, which meant it went
// empty on the last day of a week — exactly when "what's coming up" is the
// thing you actually want to see. It now appends next week's sheet (the one
// resolveWeekTabs declined to promote, window.nextTitle) under its own
// heading. Days already carrying a fatigue value are filtered out of both
// blocks, same rule as before.
        async function loadFutureData() {
            const content = document.getElementById('content-futuros');
            content.innerHTML = '';

            if (!window.currentData || !window.currentData.values) {
                content.innerHTML = '<p class="no-data">Données non chargées. Essayez d\'actualiser.</p>';
                return;
            }

            const days = parseDays(window.currentData.values, window.currentData.sheet_name);
            const activeDays = days.filter(d => d.exercises.length > 0);

            // Find index of current workout (first one without fatigue value)
            const currentIndex = activeDays.findIndex(d => !d.hasFatigueValue);
            
            let futureDays = [];
            if (currentIndex !== -1) {
                // Get all days AFTER the current one
                // And explicitly filter for those without fatigue (as per requirements, though implied by logic)
                futureDays = activeDays.slice(currentIndex + 1).filter(d => !d.hasFatigueValue);
            }

            let rendered = false;
            if (futureDays.length > 0) {
                renderDaysList(futureDays, 'content-futuros', true, true);
                rendered = true;
            }

            // Next week's sheet, when one exists and hasn't been promoted yet.
            const nextTitle = (typeof window !== 'undefined') ? window.nextTitle : null;
            if (nextTitle) {
                try {
                    if (!nextWeekCache || nextWeekCache.title !== nextTitle) {
                        nextWeekCache = { title: nextTitle, data: await sheetsClient.getTab(nextTitle) };
                    }
                    const nextData = nextWeekCache.data;
                    const nextDays = parseDays(nextData.values, nextData.sheet_name)
                        .filter(d => d.exercises.length > 0 && !d.hasFatigueValue);

                    if (nextDays.length > 0) {
                        appendWeekHeading(content, 'Semaine prochaine — ' + nextData.sheet_name);
                        renderDaysList(nextDays, 'content-futuros', true, true);
                        rendered = true;
                    }
                } catch (err) {
                    // A failed fetch must not wipe the days already rendered
                    // above; show the error only when there is nothing else.
                    console.error('Error fetching next week data:', err);
                    if (!rendered) {
                        content.innerHTML = '<p class="no-data">Erreur lors du chargement de la semaine prochaine : ' + err.message + '</p>';
                        return;
                    }
                }
            }

            if (!rendered) {
                content.innerHTML = '<p class="no-data">Pas encore d\'entraînements à venir.</p>';
            }
        }

// loadPastData — academia.html:583-650, two enumerated changes:
//   1. the fetch(buildApiUrl('/ws2/entrainement/past_data')) call
//      (Response.ok/.json handling included, since that's the fetch
//      mechanics being replaced) is swapped for sheetsClient.getPastTab(),
//      which returns the parsed {sheet_name, values} directly and throws
//      instead of returning {error: ...}.
//   2. the "rolling window" is dropped (bug fix). It used to slice the
//      first `currentCompletedDays.length` days off the FRONT of the
//      previous week so the tab always held a fixed number of days, which
//      meant last week's workouts disappeared one by one as this week
//      progressed. The tab now shows every day of the previous week sheet
//      plus every already-completed day of the current week.
        async function loadPastData() {
            if (pastDataLoaded) return;
            
            const loading = document.getElementById('loading-passados');
            const error = document.getElementById('error-passados');
            const content = document.getElementById('content-passados');
            
            loading.style.display = 'block';
            content.innerHTML = '';
            error.style.display = 'none';

            try {
                // 1. Fetch Previous Week Data
                // The past sheet is whichever one resolveWeekTabs put behind the
                // current week — not blindly index -2, which is the wrong sheet
                // whenever the window has slid back onto an unfinished week.
                // window.pastTitle is undefined only when no load has resolved a
                // window yet; null means "resolved, and there is no older sheet"
                // (don't fall back to getPastTab() there — index -2 would be the
                // current week itself).
                const resolvedPastTitle = (typeof window !== 'undefined') ? window.pastTitle : undefined;
                let pastDataRaw = null;
                if (resolvedPastTitle) {
                    pastDataRaw = await sheetsClient.getTab(resolvedPastTitle);
                } else if (resolvedPastTitle === undefined) {
                    pastDataRaw = await sheetsClient.getPastTab();
                }

                // 2. Parse Past Data
                let pastDays = [];
                if (pastDataRaw && pastDataRaw.values) {
                    pastDays = parseDays(pastDataRaw.values, pastDataRaw.sheet_name).filter(d => d.exercises.length > 0);
                }

                // 3. Get Completed Days from Current Week
                let currentCompletedDays = [];
                if (window.currentData && window.currentData.values) {
                    const currentDays = parseDays(window.currentData.values, window.currentData.sheet_name);
                    currentCompletedDays = currentDays.filter(d => d.exercises.length > 0 && d.hasFatigueValue);
                }

                // 4. Combine — the WHOLE previous week, then this week's
                // completed days appended in sheet order. No trimming: every
                // day of the previous week stays visible all week long.
                const daysToShow = [...pastDays, ...currentCompletedDays];

                if (daysToShow.length === 0) {
                    content.innerHTML = '<p class="no-data">Aucun entraînement passé trouvé.</p>';
                } else {
                    renderDaysList(daysToShow, 'content-passados', false); // isReadOnly = false (Editable!)
                }

                pastDataLoaded = true;

            } catch (err) {
                console.error('Error fetching past data:', err);
                error.textContent = 'Erreur lors du chargement des entraînements passé : ' + err.message;
                error.style.display = 'block';
            } finally {
                loading.style.display = 'none';
            }
        }


// window.sheetName = '' — academia.html:652. Not covered by any H1 table
// range (sits between loadPastData and toggleSettings), but parseDays/
// renderDay fall back to it (`day.sheetName || window.sheetName`). Kept,
// guarded so a node require doesn't throw on an undefined `window`.
if (typeof window !== 'undefined') {
    window.sheetName = '';
}

// toggleSettings / togglePastLoad — academia.html:654-667, one enumerated
// change: setCookie('show_past_load', ...) -> sheetsClient.setSettings
// ({showPastLoad: ...}) (localStorage, via sheets.js's settings API from
// S3). This also fixes the iOS Safari ITP 7-day script-cookie cap that made
// the toggle reset weekly on the iPhone.
// renderVersionInfo — new (no academia.html counterpart). Fills the settings
// menu's version footer.
//
// Two separate facts, because they fail independently:
//   1. CACHE_VERSION from config.js — the version of the JS that is RUNNING
//      right now. This is the one that answers "did my reload pick up the
//      deploy?", and it is bumped by hand on every release (README, "How to
//      release a new version").
//   2. The service worker's live shell cache (`entr-shell-<version>`, read
//      back from the Cache Storage API). sw.js carries its own copy of
//      CACHE_VERSION, so the two can disagree — a stale SW still serving an
//      old shell is exactly the failure this footer is meant to expose, and
//      it gets flagged in amber rather than silently ignored.
async function renderVersionInfo() {
    if (typeof document === 'undefined') return;

    const versionEl = document.getElementById('version-value');
    const swEl = document.getElementById('version-sw');
    const version = (typeof CACHE_VERSION !== 'undefined' && CACHE_VERSION) ? CACHE_VERSION : 'inconnue';

    if (versionEl) versionEl.textContent = version;
    if (!swEl) return;

    swEl.className = '';

    if (typeof caches === 'undefined' || !caches.keys) {
        swEl.textContent = 'Service worker : indisponible';
        return;
    }

    try {
        const keys = await caches.keys();
        const shellKey = keys.find(k => k.indexOf('entr-shell-') === 0);
        if (!shellKey) {
            swEl.textContent = 'Service worker : pas encore installé';
            return;
        }
        const swVersion = shellKey.slice('entr-shell-'.length);
        if (swVersion === version) {
            swEl.textContent = 'Service worker : à jour';
        } else {
            swEl.className = 'stale';
            swEl.textContent = 'Service worker : ' + swVersion + ' (obsolète — rechargez)';
        }
    } catch (e) {
        console.warn('Version info unavailable:', e);
        swEl.textContent = 'Service worker : inconnu';
    }
}

