// refreshCache — rewrite (transport change, academia.html:678-729). The SBD
// Charts half of the parallel fetch is dropped (Perfs is gone). What
// remains is functionally identical to before: clear the local tab cache,
// then reload the page — the DOMContentLoaded handler below re-fetches from
// the network on load, so a stale-cache reload always shows fresh data,
// exactly like the old server-refresh-then-reload did. Same button icon,
// same disabled+spinner-dots state, same catch/alert with the same French
// text.
async function refreshCache() {
    const btn = document.getElementById('refreshBtn');
    if (!btn) return;

    const originalContent = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<span style="font-size:1.5em; line-height:0;">...</span>';

    try {
        sheetsClient.clearCache();
        location.reload();
    } catch (e) {
        console.error(e);
        alert('Erreur lors de la mise à jour du cache: ' + e.message);
        btn.disabled = false;
        btn.innerHTML = originalContent;
    }
}

// DOMContentLoaded handler — rewrite (academia.html:731-811). Same visible
// shape (loading -> content, same error div, same "Chargement des
// données..." starting text from index.html), but:
//   - pollForFreshData is dropped entirely (plan §Architecture: "background
//     fetch re-renders in place" replaces server polling — there's no
//     longer a server-side cache to poll).
//   - the old app always had a server-held credential, so it never had an
//     auth boundary; this one does. Auth.handleRedirect() consumes an
//     OAuth hash if we just came back from Google. If there's still no
//     valid token, one silent (prompt=none) redirect is attempted UNLESS
//     Auth.needsReconnect() is already true (that flag is set by
//     handleRedirect when a previous silent attempt came back
//     interaction_required) — that's what stops this from looping between
//     this page and Google's error redirect.
//   - cache-first render: if a cached current+past tab exist, render them
//     immediately (via injectPastComments, same as the network path) before
//     the network call resolves, exactly matching sheets.js's cache-first/
//     background-refetch design in the plan.
//   - a network failure after a successful cache render shows "Hors ligne —
//     données du cache" without hiding the already-rendered cached workout
//     (plan Verification #7: "an edit shows a clear failure, not a silent
//     loss", not the read path). A network failure with nothing cached
//     falls back to the original French error string, unchanged:
//     'Erreur lors du chargement des données : ' + err.message.

// resolveWeekTabs — new (no academia.html counterpart). The old code always
// treated the LAST qualifying sheet as "this week" and the one before it as
// "past". That's wrong the moment the next week's sheet exists but the
// current one still has unfinished days: the training tab jumped straight to
// JOUR 1 of the new sheet while the user was still mid-week.
//
// The rule now: the newest sheet only becomes current once it has actually
// been STARTED (at least one day with a fatigue value). Until then, if the
// previous sheet still has an unfinished day, that previous sheet stays
// current and the window slides back one (past becomes the sheet before it).
//
// `fetchTab(title)` returns the {sheet_name, values} tab or null/undefined
// when it isn't available (the cache-first path passes a cache lookup, which
// can miss). A missing tab simply leaves the default -1/-2 pair in place.
function weekActiveDays(data) {
    if (!data || !data.values) return [];
    return parseDays(data.values, data.sheet_name).filter(d => d.exercises.length > 0);
}

function weekIsStarted(data) {
    return weekActiveDays(data).some(d => d.hasFatigueValue);
}

function weekHasUnfinishedDay(data) {
    return weekActiveDays(data).some(d => !d.hasFatigueValue);
}

async function resolveWeekTabs(titles, fetchTab) {
    const lastTitle = titles[titles.length - 1];
    const prevTitle = titles.length > 1 ? titles[titles.length - 2] : null;

    const lastTab = await fetchTab(lastTitle);
    const prevTab = prevTitle ? await fetchTab(prevTitle) : null;

    if (lastTab && prevTab && !weekIsStarted(lastTab) && weekHasUnfinishedDay(prevTab)) {
        const olderTitle = titles.length > 2 ? titles[titles.length - 3] : null;
        return {
            currentTitle: prevTitle,
            currentTab: prevTab,
            pastTitle: olderTitle,
            pastTab: olderTitle ? await fetchTab(olderTitle) : null,
            // The sheet we deliberately did NOT promote — that's next week,
            // and it's what the "À venir" tab shows once this week runs out.
            nextTitle: lastTitle
        };
    }

    return {
        currentTitle: lastTitle,
        currentTab: lastTab,
        pastTitle: prevTitle,
        pastTab: prevTab,
        nextTitle: null
    };
}

if (typeof document !== 'undefined') {
    document.addEventListener('DOMContentLoaded', async () => {
        // Initialize Settings (localStorage via sheetsClient, not cookies)
        const showPast = !!(sheetsClient && sheetsClient.getSettings().showPastLoad);
        const checkbox = document.getElementById('showPastLoadCheckbox');
        renderVersionInfo();
        if (showPast) {
            document.body.classList.add('show-past-load');
            if (checkbox) checkbox.checked = true;
        } else {
            if (checkbox) checkbox.checked = false;
        }

        const loading = document.getElementById('loading');
        const error = document.getElementById('error');
        const content = document.getElementById('content');

        // --- Auth boundary ---
        // Consume any OAuth redirect hash first.
        const redirectResult = AuthAPI ? AuthAPI.handleRedirect() : { status: 'none' };
        if (redirectResult && redirectResult.appState) {
            restoreAppState(redirectResult.appState);
        }

        if (!AuthAPI || !AuthAPI.getValidToken()) {
            if (AuthAPI && AuthAPI.needsReconnect()) {
                // A previous silent attempt failed with interaction_required.
                // Don't redirect again automatically (that's the loop this
                // guards against) — show the reconnect button instead.
                loading.style.display = 'none';
                renderReconnectPrompt(error);
                return;
            }

            try {
                // Top-level redirect — nothing after this line runs if it
                // navigates away.
                AuthAPI.signIn({ silent: true, appState: currentAppState() });
                return;
            } catch (e) {
                console.error('Sign-in failed to start:', e);
                loading.style.display = 'none';
                if (error) {
                    error.textContent = AuthAPI.MESSAGES.SIGN_IN_REQUIRED + ' : ' + e.message;
                    error.style.display = 'block';
                }
                return;
            }
        }

        // --- Cache-first render ---
        let renderedFromCache = false;
        try {
            const cachedMeta = sheetsClient.getCachedMeta();
            if (cachedMeta && cachedMeta.workoutSheets && cachedMeta.workoutSheets.length > 0) {
                const titles = cachedMeta.workoutSheets;
                const resolved = await resolveWeekTabs(titles, t => sheetsClient.getCachedTab(t));
                const cachedCurrent = resolved.currentTab;
                if (cachedCurrent) {
                    const cachedPast = resolved.pastTab;
                    window.pastTitle = resolved.pastTitle;
                    window.nextTitle = resolved.nextTitle;
                    const dataToRender = cachedPast ? injectPastComments(cachedCurrent, cachedPast) : cachedCurrent;

                    window.sheetName = dataToRender.sheet_name;
                    window.currentData = dataToRender;
                    processAndRender(dataToRender, 'content', false, false, false);
                    loading.style.display = 'none';
                    content.style.display = 'block';
                    renderedFromCache = true;
                }
            }
        } catch (e) {
            console.error('Cache render error:', e);
        }

        // --- Replay edits parked by a token expiry ---
        // Runs before the read below so the re-render shows the values that
        // were just replayed, not the ones the sheet had before them.
        try {
            const replayed = await flushPendingWrites();
            if (replayed) console.log('Replayed ' + replayed + ' pending edit(s) after token renewal');
        } catch (e) {
            console.error('Pending write replay error:', e);
        }

        // --- Network fetch (always runs, to pick up changes made elsewhere) ---
        try {
            const titles = await sheetsClient.listWorkoutSheets();
            if (!titles || titles.length === 0) {
                throw new Error('Aucune feuille d\'entraînement trouvée.');
            }
            const resolved = await resolveWeekTabs(titles, t => sheetsClient.getTab(t));
            const currentTab = resolved.currentTab;
            const pastTab = resolved.pastTab;
            window.pastTitle = resolved.pastTitle;
            window.nextTitle = resolved.nextTitle;

            const data = pastTab ? injectPastComments(currentTab, pastTab) : currentTab;

            window.sheetName = data.sheet_name;
            window.currentData = data;
            processAndRender(data, 'content', false, false, false);
            loading.style.display = 'none';
            content.style.display = 'block';
            if (error) error.style.display = 'none';

        } catch (err) {
            console.error('Error fetching data:', err);
            if (renderedFromCache) {
                if (error) {
                    error.textContent = 'Hors ligne — données du cache';
                    error.style.display = 'block';
                }
            } else {
                loading.style.display = 'none';
                if (error) {
                    error.textContent = 'Erreur lors du chargement des données : ' + err.message;
                    error.style.display = 'block';
                }
            }
        }
    });
}

// updateRPE — rewrite (transport change, academia.html:813-862). The
// fetch('/ws2/entrainement/update_rpe', {user, sheet_name, row_index,
// rpe_value}) POST is replaced by sheetsClient.updateRPE(sheetName,
// rowIndex, value) (S3's client already applies the same numeric coercion
// server.py's pydantic layer used to apply, and write-through-patches the
// local cache). Same yellow -> green -> normal background feedback, same
// disabled-while-processing, same French alert() text exactly:
// 'Erreur lors de la mise à jour du RPE : ' + err.message — except when the
// failure is an expired token, which is now parked + renewed rather than
// alerted about (see ensureTokenBeforeWrite).
async function updateRPE(sheetName, rowIndex, value, element) {
    if (!value) return false;

    const pending = { kind: 'rpe', sheetName, rowIndex, colIndex: RPE_COL_INDEX, value };
    const originalBackground = element.style.backgroundColor;
    element.style.backgroundColor = '#4d3e00'; // Dark Yellow indicating processing
    element.disabled = true;

    // Token pre-flight: never PUT with a dead token — park the edit and
    // renew first. The element stays yellow (pending) while we redirect.
    if (!ensureTokenBeforeWrite(pending)) {
        element.disabled = false;
        return false;
    }

    try {
        await sheetsClient.updateRPE(sheetName, rowIndex, value);

        element.style.backgroundColor = '#1e3a20'; // Dark Green indicating success
        setTimeout(() => {
            element.style.backgroundColor = originalBackground;
            element.disabled = false;
        }, 1000);
        return true;

    } catch (err) {
        console.error('Error updating RPE:', err);
        if (handleWriteAuthFailure(err, pending)) {
            element.disabled = false;
            return false;
        }
        element.style.backgroundColor = '#3a1e1e'; // Dark Red indicating error
        alert('Erreur lors de la mise à jour du RPE : ' + err.message);
        element.disabled = false;
        return false;
    }
}

// updateCell — rewrite (transport change, academia.html:921-971). Same
// pattern as updateRPE: fetch('/ws2/entrainement/update_cell', {user,
// sheet_name, row_index, col_index, value}) -> sheetsClient.updateCell
// (sheetName, rowIndex, colIndex, value). Same yellow -> green -> normal
// feedback (respecting disableInput), same French alert() text exactly:
// 'Erreur lors de la mise à jour de la cellule : ' + err.message — except
// for an expired token, parked + renewed instead of alerted about.
async function updateCell(sheetName, rowIndex, colIndex, value, element, disableInput = true) {
    if (value === undefined || value === null) return false;

    const pending = { kind: 'cell', sheetName, rowIndex, colIndex, value };
    const originalBackground = element.style.backgroundColor;
    element.style.backgroundColor = '#4d3e00'; // Dark Yellow indicating processing
    if (disableInput) element.disabled = true;

    // Token pre-flight — see updateRPE.
    if (!ensureTokenBeforeWrite(pending)) {
        if (disableInput) element.disabled = false;
        return false;
    }

    try {
        await sheetsClient.updateCell(sheetName, rowIndex, colIndex, value);

        element.style.backgroundColor = '#1e3a20'; // Dark Green indicating success
        setTimeout(() => {
            element.style.backgroundColor = originalBackground;
            if (disableInput) element.disabled = false;
        }, 1000);
        return true;

    } catch (err) {
        console.error('Error updating Cell:', err);
        if (handleWriteAuthFailure(err, pending)) {
            if (disableInput) element.disabled = false;
            return false;
        }
        element.style.backgroundColor = '#3a1e1e'; // Dark Red indicating error
        alert('Erreur lors de la mise à jour de la cellule : ' + err.message);
        if (disableInput) element.disabled = false;
        return false;
    }
}

// debounce / debouncedUpdateCell — academia.html:973-986, byte-for-byte.
        // Debounce utility
        function debounce(func, wait) {
            let timeout;
            return function(...args) {
                const context = this;
                clearTimeout(timeout);
                timeout = setTimeout(() => func.apply(context, args), wait);
            };
        }

        // Debounced version of updateCell for auto-save (doesn't disable input)
        const debouncedUpdateCell = debounce((sheetName, rowIndex, colIndex, value, element) => {
            updateCell(sheetName, rowIndex, colIndex, value, element, false);
        }, 2000);


// updateFatigueCell — academia.html:988-1006, one enumerated change: the
// fetch(refresh) + location.reload() pair is replaced by a local cache
// refresh (listWorkoutSheets + getTab current/past, same call shape the
// DOMContentLoaded network path uses) + injectPastComments + a
// processAndRender re-render in place, instead of reloading the whole page.
// Same loading-message swap and same content-hidden-while-loading
// behaviour around it.
async function updateFatigueCell(sheetName, rowIndex, colIndex, value, element) {
    try {
        const written = await updateCell(sheetName, rowIndex, colIndex, value, element);
        // The write was parked for replay (expired token) or failed — the
        // sheet hasn't changed, so there is no next workout to load yet.
        if (!written) return;

        // Completing a day changes what "Passé" must show, so make the tab
        // re-fetch instead of serving the list it built earlier this session.
        pastDataLoaded = false;
        nextWeekCache = null;

        // Show loading state
        const loading = document.getElementById('loading');
        if(loading) {
            loading.style.display = 'block';
            loading.textContent = 'Mise à jour du cache et chargement du prochain entraînement...';
        }
        document.getElementById('content').style.display = 'none';

        // Refresh cache and re-render (was: fetch(refresh) + location.reload())
        const titles = await sheetsClient.listWorkoutSheets();
        const resolved = await resolveWeekTabs(titles, t => sheetsClient.getTab(t));
        const currentTab = resolved.currentTab;
        const pastTab = resolved.pastTab;
        window.pastTitle = resolved.pastTitle;
        window.nextTitle = resolved.nextTitle;

        const data = pastTab ? injectPastComments(currentTab, pastTab) : currentTab;

        window.sheetName = data.sheet_name;
        window.currentData = data;
        processAndRender(data, 'content', false, false, false);

        if (loading) loading.style.display = 'none';
        document.getElementById('content').style.display = 'block';
    } catch (e) {
        console.error("Fatigue update failed", e);
    }
}

// renderDaysList — academia.html:1008-1018, byte-for-byte.
        function renderDaysList(days, containerId, isReadOnly, hideExtras = false) {
             const content = document.getElementById(containerId);
             
             days.forEach(day => {
                 const dayHeader = document.createElement('h3');
                 dayHeader.style.cssText = 'margin: 20px 0 10px 0; color: #4dabf7; text-transform: uppercase; font-size: 0.9em; letter-spacing: 1px; border-bottom: 1px solid #333; padding-bottom: 5px;';
                 dayHeader.textContent = day.name || 'Jour Inconnu';
                 content.appendChild(dayHeader);
                 renderDay(day, content, isReadOnly, hideExtras);
             });
        }

// processAndRender — academia.html:1020-1065, one enumerated change: the
// three fetch(buildApiUrl('/ws2/entrainement/clear_cache'), {method:
// 'POST'}) calls become sheetsClient.clearCache() (synchronous, local —
// the .then/.catch logging on the "end of sheet" branch is kept as a
// try/catch around the synchronous call instead, same two console
// messages). Nothing else touched.
        function processAndRender(data, containerId = 'content', isReadOnly = false, hideExtras = false, tempReadOnly = false) {
            const content = document.getElementById(containerId);
            content.innerHTML = '';

            if (!data.values || data.values.length === 0) {
                content.innerHTML = '<p class="no-data">Aucune donnée trouvée dans la feuille.</p>';
                if (!isReadOnly) sheetsClient.clearCache();
                return;
            }

            const days = parseDays(data.values, data.sheet_name);
            // Filter days with no exercises
            const activeDays = days.filter(d => d.exercises.length > 0);

            if (isReadOnly) {
                if (activeDays.length === 0) {
                     content.innerHTML = '<p class="no-data">Aucun entraînement trouvé cette semaine.</p>';
                } else {
                     renderDaysList(activeDays, containerId, true, hideExtras);
                }
                return;
            }

            // Find first day without fatigue value
            const targetDay = activeDays.find(d => !d.hasFatigueValue);

            if (targetDay) {
                // When rendering the single active day, we might pass tempReadOnly if loading from cache
                // But generally for the main view 'isReadOnly' is false.
                renderDay(targetDay, content, tempReadOnly, hideExtras);
            } else if (activeDays.length > 0) {
                 // All days completed. Show message AND the last workout as requested.
                 content.innerHTML = '<p class="no-data" style="margin-bottom: 12px;">Tous les entraînements ont été complétés !</p>';

                 const lastDay = activeDays[activeDays.length - 1];
                 renderDay(lastDay, content, tempReadOnly, hideExtras);

                 // Clear cache because we are done with this sheet
                 try {
                    sheetsClient.clearCache();
                    console.log('Cache cleared (end of sheet)');
                 } catch (e) {
                    console.error('Error clearing cache', e);
                 }
            } else {
                 content.innerHTML = '<p class="no-data">Aucun entraînement trouvé.</p>';
                 sheetsClient.clearCache();
            }
        }


// normalizeText, getCommentCoordinates — academia.html:1067-1079,
// byte-for-byte.
        function normalizeText(text) {
            return text.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
        }

        function getCommentCoordinates(dayNum) {
            // Centralized logic for Comment Cell location
            // Column O is index 14
            // Day 1 starts at Row 23, step 15 (Day 2 = 38, etc.)
            return {
                rowIndex: 23 + (dayNum - 1) * 15,
                colIndex: 14
            };
        }

// parseDays — academia.html:1081-1297, byte-for-byte (217 lines, the
// highest-risk copy: merged-Séries carry-over, the dynamic fatigue-label
// scan, JOUR 3 -> H41, JOUR 5 -> H71). Copied whole, nothing changed.
        function parseDays(rows, sheetName) {
            const days = [];
            let currentDay = null;
            let lastExerciseRowIndex = -1;
            // Variable to track the last valid "Sets" value for merged cells
            let lastSets = null;
            const currentSheetName = sheetName || window.sheetName;

            const isValidFatigueValue = (val) => {
                if (val === null || val === undefined) return false;
                const s = val.toString().trim();
                if (s === '') return false;
                const n = parseFloat(s.replace(',', '.'));
                return !isNaN(n) && n >= 0 && n <= 10;
            };

            rows.forEach((row, rowIndex) => {
                let isExerciseRow = false;

                // Check for start of new day (JOUR X) - Column C (index 2)
                if (row[2] && typeof row[2] === 'string' && row[2].toUpperCase().includes('JOUR')) {
                    if (currentDay) {
                        days.push(currentDay);
                    }
                    currentDay = {
                        name: row[2],
                        exercises: [],
                        hasFatigueValue: false,
                        fatiguePhysique: null,
                        fatiguePsy: null,
                        fatiguePost: null,
                        comment: null,
                        sheetName: currentSheetName
                    };
                    
                    // Reset lastSets when a new day starts
                    lastSets = null;

                    // Extract Comment Data based on Day Number
                    const dayMatch = row[2].match(/JOUR\s*(\d+)/i);
                    if (dayMatch) {
                        const dayNum = parseInt(dayMatch[1]);
                        const coords = getCommentCoordinates(dayNum);
                        
                        // Check bounds (coords.rowIndex is 1-based)
                        if (rows.length >= coords.rowIndex) {
                             const dataRow = rows[coords.rowIndex - 1]; // 0-based array index
                             const commentValue = (dataRow && dataRow[coords.colIndex]) ? dataRow[coords.colIndex] : '';
                             
                             currentDay.comment = {
                                 rowIndex: coords.rowIndex,
                                 colIndex: coords.colIndex,
                                 value: commentValue
                             };
                        }
                    }
                }

                if (currentDay) {
                    // Check for Exercises
                    const exerciseName = row[6] ? row[6].toString().trim() : '';
                    let setsStr = row[10] ? row[10].toString().trim() : '';

                    // Handle Merged Sets Cells (Fusion logic)
                    if (exerciseName && exerciseName.toUpperCase() !== 'EXERCICE' && !exerciseName.toUpperCase().includes('JOUR')) {
                         if (setsStr) {
                             lastSets = setsStr;
                         } else if (lastSets) {
                             setsStr = lastSets;
                         }
                    } else if (!exerciseName) {
                        // Reset on empty rows to prevent leakage across gaps
                        lastSets = null;
                    }

                    if (exerciseName && 
                        exerciseName.toUpperCase() !== 'EXERCICE' && 
                        !exerciseName.toUpperCase().includes('JOUR') &&
                        setsStr) {
                         // Extract details
                        const sets = setsStr;
                        const safeStr = (val) => (val === null || val === undefined) ? '' : val.toString();
                        
                        const reps = safeStr(row[11]);
                        const rpeDonne = safeStr(row[12]); // RPE donné
                        const charge = safeStr(row[13]);
                        const currentRpe = safeStr(row[14]); // RPE perçu (Column O)
                        const comment = safeStr(row[17]); // Commentaire (Column R)

                        currentDay.exercises.push({
                            name: exerciseName,
                            sets: sets,
                            reps: reps,
                            rpe: rpeDonne,
                            load: charge,
                            rowIndex: rowIndex + 1, // Store 1-based row index for API
                            currentRpe: currentRpe,
                            comment: comment
                        });
                        isExerciseRow = true;
                    }

                    // ...
                    // Check for Fatigue Labels Dynamically
                    row.forEach((cell, colIndex) => {
                        if (cell && (typeof cell === 'string' || typeof cell === 'number')) {
                            const normalizedCell = normalizeText(cell.toString());
                            
                            // Helper to find value to the right (skips empty cells)
                            const findValue = (startCol, defaultOffset, searchLimit = 3) => {
                                // Search up to searchLimit cells to the right for a value
                                for (let i = 1; i <= searchLimit; i++) {
                                    const targetCol = startCol + i;
                                    const val = row[targetCol];
                                    if (val !== undefined && val !== null && val.toString().trim() !== '') {
                                        return {
                                            rowIndex: rowIndex + 1,
                                            colIndex: targetCol,
                                            value: val
                                        };
                                    }
                                }
                                // Not found, return default position (likely empty)
                                return {
                                    rowIndex: rowIndex + 1,
                                    colIndex: startCol + defaultOffset,
                                    value: null
                                };
                            };

                            // Fatigue Physique
                            if (normalizedCell.includes('fatigue physique') || normalizedCell.includes('fadiga fisica')) {
                                // User request: Always Column H (Index 7)
                                currentDay.fatiguePhysique = {
                                    rowIndex: rowIndex + 1,
                                    colIndex: 7,
                                    value: row[7]
                                };
                            } 
                            // Fatigue Psy
                            else if (normalizedCell.includes('fatigue psy') || normalizedCell.includes('fatigue mentale') || normalizedCell.includes('fatigue mental') || normalizedCell.includes('fadiga mental') || normalizedCell.includes('fadiga psy')) {
                                currentDay.fatiguePsy = findValue(colIndex, 2);
                            } 
                            // Fatigue Post-Workout
                            // Matches "niveau de fatigue après la séance", "fadiga pós-sessão", etc.
                            else if ((normalizedCell.includes('fatigue') || normalizedCell.includes('fadiga')) && 
                                     (normalizedCell.includes('apres') || normalizedCell.includes('após') || normalizedCell.includes('seance') || normalizedCell.includes('sessao') || normalizedCell.includes('pos'))) {
                                
                                // Centralized Logic: Always Column K (Index 10)
                                const val = row[10];
                                const valData = {
                                    rowIndex: rowIndex + 1,
                                    colIndex: 10,
                                    value: val
                                };

                                currentDay.fatiguePost = valData;
                                
                                // Update completion status based on this value
                                if (val !== null && isValidFatigueValue(val)) {
                                    currentDay.hasFatigueValue = true;
                                    console.log(`Day ${currentDay.name} marked as done. Fatigue Post value: ${val}`);
                                } else {
                                     console.log(`Day ${currentDay.name} Post Fatigue: No valid value found in Column K.`);
                                }
                            }
                        }
                    });
                }
                
                if (isExerciseRow) {
                    lastExerciseRowIndex = rowIndex;
                }
            });

            // Push the last day
            if (currentDay) {
                days.push(currentDay);
            }

            // Fix for Day 3 Physical Fatigue and Post-Workout
            const day3 = days.find(d => d.name && d.name.toUpperCase().includes('JOUR 3'));
            if (day3) {
                 // Physical Fatigue (Correct is H41)
                 const overrideRowIndex = 41; // 1-based
                 const overrideColIndex = 7;  // 0-based (H)
                 
                 // Ensure we have the data
                 if (rows.length >= overrideRowIndex) {
                     const val = rows[overrideRowIndex - 1][overrideColIndex];
                     day3.fatiguePhysique = {
                         rowIndex: overrideRowIndex,
                         colIndex: overrideColIndex,
                         value: val
                     };
                 }
            }

            // Fix for Day 5 Post-Workout Fatigue (User reported mapping error, correct is K83)
            const day5 = days.find(d => d.name && d.name.toUpperCase().includes('JOUR 5'));
            if (day5) {
                 // Physical Fatigue (Correct is H71)
                 const overrideRowIndex = 71; // 1-based
                 const overrideColIndex = 7;  // 0-based (H)
                 
                 if (rows.length >= overrideRowIndex) {
                     const val = rows[overrideRowIndex - 1][overrideColIndex];
                     day5.fatiguePhysique = {
                         rowIndex: overrideRowIndex,
                         colIndex: overrideColIndex,
                         value: val
                     };
                 }
            }

            return days;
        }

// renderDay — academia.html:1299-1486, byte-for-byte (inline styles and
// template literals included).
        function renderDay(day, container, isReadOnly = false, hideExtras = false) {
            // Render Cards Container
            const cardsContainer = document.createElement('div');
            cardsContainer.className = 'cards-container';
            const sheetName = day.sheetName || window.sheetName;
            
            // Render Exercises
            day.exercises.forEach(ex => {
                const card = document.createElement('div');
                card.className = 'exercise-card';

                let detailsHtml = `
                    <div class="detail-item">
                        <span class="detail-label">Séries</span>
                        <span class="detail-value highlight">${ex.sets}</span>
                    </div>
                    <div class="detail-item">
                        <span class="detail-label">reps</span>
                        <span class="detail-value highlight">${ex.reps}</span>
                    </div>
                `;

                if (ex.rpe && ex.rpe.trim() !== '') {
                    // Scenario: Target RPE (RPE Alvo) is provided.
                    // 1. Carga as Input or Text
                    detailsHtml += `<div class="detail-item"><span class="detail-label">Charge</span>`;
                    
                    if (isReadOnly) {
                        detailsHtml += `<span class="detail-value">${ex.load || '-'}</span>`;
                    } else {
                        // Temp readonly for cache loading
                        const disabledAttr = ''; // Should be passed if we want temp disable
                        const disabledStyle = '';
                         detailsHtml += `
                            <input type="text" class="rpe-select"
                                   style="width: 60px; text-align: center; ${disabledStyle}"
                                   value="${ex.load || ''}"
                                   ${disabledAttr}
                                   oninput="debouncedUpdateCell('${sheetName}', ${ex.rowIndex}, 13, this.value, this)"
                                   onchange="updateCell('${sheetName}', ${ex.rowIndex}, 13, this.value, this)" />
                        `;
                    }
                    detailsHtml += `</div>`;

                    // 2. Show RPE (Alvo) as just "RPE" (Read-only output)
                    detailsHtml += `
                        <div class="detail-item">
                            <span class="detail-label">RPE</span>
                            <span class="detail-value">${ex.rpe}</span>
                        </div>
                    `;
                } else {
                    // Scenario: No Target RPE provided (Standard behavior)
                    if (ex.load && ex.load.trim() !== '') {
                        detailsHtml += `
                            <div class="detail-item">
                                <span class="detail-label">Charge</span>
                                <span class="detail-value">${ex.load}</span>
                            </div>
                        `;

                        // RPE Selection
                        detailsHtml += `<div class="detail-item"><span class="detail-label">RPE</span>`;
                        
                        if (isReadOnly) {
                            detailsHtml += `<span class="detail-value">${ex.currentRpe || '-'}</span>`;
                        } else {
                             let optionsHtml = '<option value="">Sél...</option>';
                            for (let val = 6; val <= 10; val += 0.5) {
                                const selected = (ex.currentRpe && parseFloat(ex.currentRpe.replace(',','.')) === val) ? 'selected' : '';
                                optionsHtml += `<option value="${val}" ${selected}>${val}</option>`;
                            }
                            detailsHtml += `
                                <select class="rpe-select" onchange="updateRPE('${sheetName}', ${ex.rowIndex}, this.value, this)">
                                    ${optionsHtml}
                                </select>
                            `;
                        }
                        detailsHtml += `</div>`;
                    }
                }

                if (ex.comment && ex.comment.trim() !== '') {
                    // Check for "Passé:" line
                    let commentHtml = '';
                    let rawComment = ex.comment.trim();
                    let pastLine = '';
                    let userComment = rawComment;

                    if (rawComment.startsWith('Passé:')) {
                        const parts = rawComment.split('\n');
                        pastLine = parts[0]; // The first line is the auto-generated past info
                        userComment = parts.slice(1).join('\n').trim(); // The rest is user comment
                    }

                    if (pastLine) {
                         commentHtml += `<div class="past-perf-line">${pastLine}</div>`;
                    }
                    
                    if (userComment) {
                        commentHtml += `<div class="user-comment-line">${userComment}</div>`;
                    }
                    
                    detailsHtml += commentHtml;
                }

                card.innerHTML = `
                    <div class="exercise-name">${ex.name}</div>
                    <div class="exercise-details" style="flex-wrap: wrap;">
                        ${detailsHtml}
                    </div>
                `;

                cardsContainer.appendChild(card);
            });

            // Render Fatigue Card (After Exercises)
            if (!hideExtras && (day.fatiguePhysique || day.fatiguePsy || day.fatiguePost)) {
                const fatigueCard = document.createElement('div');
                fatigueCard.className = 'exercise-card';
                fatigueCard.style.borderLeft = '4px solid #9c27b0'; // Purple

                let fatigueHtml = `<div class="exercise-name">Fatigue</div><div class="exercise-details">`;

                const renderFatigueInput = (label, data, isPostWorkout = false) => {
                    if (!data) return '';
                    
                    let content = `<div class="detail-item"><span class="detail-label">${label}</span>`;
                    
                    if (isReadOnly) {
                         content += `<span class="detail-value">${data.value || '-'}</span>`;
                    } else {
                        let options = '<option value="">Sél...</option>';
                        for (let i = 1; i <= 10; i++) {
                            const selected = (data.value && parseInt(data.value) == i) ? 'selected' : '';
                            options += `<option value="${i}" ${selected}>${i}</option>`;
                        }
                        const updateFn = isPostWorkout ? 'updateFatigueCell' : 'updateCell';
                        
                        content += `
                            <select class="rpe-select" onchange="${updateFn}('${sheetName}', ${data.rowIndex}, ${data.colIndex}, this.value, this)">
                                ${options}
                            </select>
                        `;
                    }
                    content += `</div>`;
                    return content;
                };

                fatigueHtml += renderFatigueInput('Physique', day.fatiguePhysique);
                fatigueHtml += renderFatigueInput('Mentale', day.fatiguePsy);
                fatigueHtml += renderFatigueInput('Post-Entraînement', day.fatiguePost, true);

                fatigueHtml += `</div>`;
                fatigueCard.innerHTML = fatigueHtml;
                cardsContainer.appendChild(fatigueCard);
            }

            // Render Comment Card
            if (!hideExtras && day.comment) {
                const commentCard = document.createElement('div');
                commentCard.className = 'exercise-card';

                let commentContent = '';
                if (isReadOnly) {
                     commentContent = `<div style="width: 100%; min-height: 40px; background: transparent; color: #e0e0e0; padding: 10px; font-style: italic;">${day.comment.value || 'Aucun commentaire.'}</div>`;
                } else {
                     commentContent = `
                        <textarea
                            style="width: 100%; min-height: 80px; background: #2a2a2a; border: 1px solid #444; color: #e0e0e0; padding: 10px; border-radius: 4px; resize: vertical; font-family: inherit; font-size: 1em; box-sizing: border-box;"
                            placeholder="Écrivez vos commentaires sur l'entraînement ici..."
                            oninput="debouncedUpdateCell('${sheetName}', ${day.comment.rowIndex}, ${day.comment.colIndex}, this.value, this)"
                            onchange="updateCell('${sheetName}', ${day.comment.rowIndex}, ${day.comment.colIndex}, this.value, this)"
                        >${day.comment.value || ''}</textarea>
                    `;
                }

                commentCard.innerHTML = `
                    <div class="exercise-name">Commentaires</div>
                    <div class="exercise-details" style="display: block;">
                        ${commentContent}
                    </div>
                `;
                cardsContainer.appendChild(commentCard);
            }

            container.appendChild(cardsContainer);
        }

// node --test usage: CommonJS export tail (H3 — parseDays, injectPastComments
